BEGIN;

CREATE TABLE IF NOT EXISTS zigo.booking_billing_snapshots (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  service_request_id uuid NOT NULL UNIQUE REFERENCES zigo.service_requests(id) ON DELETE CASCADE,
  base_price_paise bigint DEFAULT 0 NOT NULL,
  discount_paise bigint DEFAULT 0 NOT NULL,
  selling_price_paise bigint DEFAULT 0 NOT NULL,
  item_total_paise bigint DEFAULT 0 NOT NULL,
  tax_amount_paise bigint DEFAULT 0 NOT NULL,
  inclusive_tax_amount_paise bigint DEFAULT 0 NOT NULL,
  exclusive_tax_amount_paise bigint DEFAULT 0 NOT NULL,
  tip_amount_paise bigint DEFAULT 0 NOT NULL,
  waiting_charges_paise bigint DEFAULT 0 NOT NULL,
  grand_total_paise bigint DEFAULT 0 NOT NULL,
  currency text DEFAULT 'INR' NOT NULL,
  tax_details jsonb DEFAULT '[]'::jsonb NOT NULL,
  pricing_details jsonb DEFAULT '{}'::jsonb NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  updated_at timestamptz DEFAULT now() NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_booking_billing_snapshots_request ON zigo.booking_billing_snapshots(service_request_id);

CREATE TABLE IF NOT EXISTS zigo.booking_invoice_email_jobs (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  booking_id uuid NOT NULL UNIQUE REFERENCES zigo.service_requests(id) ON DELETE CASCADE,
  customer_user_id uuid NOT NULL REFERENCES zigo.users(id) ON DELETE CASCADE,
  status text DEFAULT 'pending' NOT NULL CHECK (status IN ('pending','processing','retry','sent','skipped','failed')),
  attempt_count integer DEFAULT 0 NOT NULL,
  next_attempt_at timestamptz DEFAULT now() NOT NULL,
  locked_at timestamptz,
  sent_at timestamptz,
  last_error text,
  created_at timestamptz DEFAULT now() NOT NULL,
  updated_at timestamptz DEFAULT now() NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_booking_invoice_email_jobs_due ON zigo.booking_invoice_email_jobs(next_attempt_at, id) WHERE status IN ('pending','retry','processing');

CREATE TABLE IF NOT EXISTS zigo.customer_support_tickets (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  ticket_number varchar(32) NOT NULL UNIQUE,
  customer_id uuid NOT NULL REFERENCES zigo.customers(id),
  booking_id uuid REFERENCES zigo.service_requests(id),
  subject varchar(200) NOT NULL,
  category varchar(60) DEFAULT 'general' NOT NULL,
  status_code varchar(30) DEFAULT 'open' NOT NULL,
  priority_code varchar(20) DEFAULT 'normal' NOT NULL,
  assigned_admin_user_id uuid REFERENCES zigo.users(id),
  last_message_at timestamptz DEFAULT now() NOT NULL,
  closed_at timestamptz,
  metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  updated_at timestamptz DEFAULT now() NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_customer_support_tickets_customer ON zigo.customer_support_tickets(customer_id, last_message_at DESC);
CREATE INDEX IF NOT EXISTS idx_customer_support_tickets_status ON zigo.customer_support_tickets(status_code, priority_code, last_message_at DESC);

CREATE TABLE IF NOT EXISTS zigo.customer_support_messages (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  ticket_id uuid NOT NULL REFERENCES zigo.customer_support_tickets(id) ON DELETE CASCADE,
  sender_type varchar(20) NOT NULL,
  sender_user_id uuid REFERENCES zigo.users(id),
  message text NOT NULL,
  metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_customer_support_messages_ticket ON zigo.customer_support_messages(ticket_id, created_at);

CREATE TABLE IF NOT EXISTS zigo.tax_master_rules (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  tax_applicable_on text DEFAULT 'selling_price' NOT NULL,
  tax_applicability text DEFAULT 'exclusive' NOT NULL,
  tax_type text DEFAULT 'percent' NOT NULL,
  tax_value numeric(12,2) DEFAULT 0 NOT NULL,
  formula text DEFAULT '(Tax Applicable On Price x Tax Value / (100+tax value))' NOT NULL,
  tax_label text NOT NULL,
  tax_note text,
  metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
  is_active boolean DEFAULT true NOT NULL,
  created_by uuid REFERENCES zigo.users(id),
  created_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid REFERENCES zigo.users(id),
  updated_at timestamptz DEFAULT now() NOT NULL,
  deleted_by uuid REFERENCES zigo.users(id),
  deleted_at timestamptz,
  is_deleted boolean DEFAULT false NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_tax_master_rules_active ON zigo.tax_master_rules(is_deleted, is_active, created_at DESC);
CREATE TEMP TABLE seed_categories (LIKE zigo.categories INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE seed_booking_engine_quick_replies (LIKE zigo.booking_engine_quick_replies INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE seed_category_price_rules (LIKE zigo.category_price_rules INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE seed_category_service_masters (LIKE zigo.category_service_masters INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE seed_payment_mode_masters (LIKE zigo.payment_mode_masters INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE seed_tax_master_rules (LIKE zigo.tax_master_rules INCLUDING DEFAULTS) ON COMMIT DROP;







COMMIT;